--
-- Name: assert_member_owner_guard(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.assert_member_owner_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_codes text[];
  v_bad   text;
begin
  -- ============================================================================
  -- REV3-FIX（P0-3）：重写为"提交时不变量断言"。
  --
  -- 【v1/v2/REV3 的缺口（独立复审确认）】
  --   旧实现按事件时刻的 OLD/NEW 行身份过滤（"只盯 owner 自己的行"）：
  --     · UPDATE 分支只读 NEW.space_id / NEW.user_id ——
  --       `UPDATE space_members SET user_id = 'x' WHERE ...`（owner 行）会因
  --       NEW.user_id <> owner 直接 return null 放行；
  --       `UPDATE space_members SET space_id = 'Y' WHERE ...`（owner 行搬走）
  --       同样放行 —— 两种改写都让未归档空间在提交时失去有效 owner，
  --       且提交时不再有任何触发器拦得住（spaces 侧触发器只监听 spaces 列）。
  --     · 不变量的正确性不得依赖"普通客户端没有 space_members UPDATE 授权"
  --       （DEFINER 函数、未来授权变更、直接 SQL 运维都可能绕过）。
  --
  -- 【新语义：不变量即断言，与 C4 审计完全同构】
  --   对**本次事件涉及的空间集合**（DELETE→OLD.space_id；INSERT→NEW.space_id；
  --   UPDATE→OLD 与 NEW 的 space_id 并集 —— 跨空间改写会涉及两个空间）：
  --     提交时，凡未归档且 owner_user_id 非空的空间 s，
  --     必须存在 (space_id=s.code, user_id=s.owner_user_id, left_at is null) 的成员行。
  --
  -- 【OLD/NEW 快照 vs 提交时实际状态（DEFERRABLE INITIALLY DEFERRED）】
  --   延迟行级触发器在**提交时**逐事件触发，每个事件携带的是**事件时刻**的
  --   OLD/NEW 快照；但触发器执行时全部数据修改已完成，表内即**最终状态**。
  --   因此本函数：只用 OLD/NEW 识别"涉及哪些空间"（身份可能已被改写，
  --   快照恰恰是发现改写的唯一线索），判定一律**重读提交时状态**。
  --   这保证：
  --     · 同一事务内"临时改坏 → 再改回来"的多条 UPDATE，各事件快照虽有
  --       违规瞬间，但提交时不变量成立 → 全部放行（不误拒绝最终合法变更）；
  --     · dissolve 同事务"先全员退出后归档"（或反序）：提交时 spaces 已归档
  --       → 豁免，合法解散不受影响；
  --     · 创建（先 spaces 后 members）与重加（复活 left_at=null）：提交时
  --       不变量成立 → 放行。
  -- ============================================================================
  if tg_op = 'DELETE' then
    v_codes := array[old.space_id];
  elsif tg_op = 'INSERT' then
    v_codes := array[new.space_id];
  else                                        -- UPDATE：OLD 与 NEW 可能涉及不同空间
    v_codes := array[old.space_id, new.space_id];
  end if;

  select s.code into v_bad
    from public.spaces s
   where s.code = any(v_codes)
     and s.archived_at is null                 -- 提交时已归档：豁免（X1）
     and s.owner_user_id is not null
     and not exists (                          -- 提交时 owner 必须有有效成员行
       select 1 from public.space_members m
        where m.space_id = s.code
          and m.user_id   = s.owner_user_id
          and m.left_at is null
     )
   limit 1;

  if v_bad is not null then
    raise exception 'owner_not_active_member_at_commit: %', v_bad
      using errcode = '23514',
            hint = '未归档空间的 owner 在提交时必须存在有效成员行（user_id/space_id/left_at 不得被改写成破坏该不变量）';
  end if;

  return null;
end;
$$;



--
-- Name: assert_space_owner_is_member(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.assert_space_owner_is_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner    text;
  v_archived timestamptz;
begin
  select s.owner_user_id, s.archived_at
    into v_owner, v_archived
    from public.spaces s
   where s.code = new.code;

  if v_archived is not null then return null; end if;   -- 已归档：成员必然全退出
  if v_owner is null        then return null; end if;   -- unclaimed：无 owner 可断言

  if not exists (
    select 1 from public.space_members m
     where m.space_id = new.code and m.user_id = v_owner and m.left_at is null
  ) then
    raise exception 'owner_not_active_member: %', new.code
      using errcode = '23514', hint = 'owner_user_id 必须指向该空间的有效成员';
  end if;

  return null;
end;
$$;



--
-- Name: audit_event(text, text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.audit_event(p_action text, p_actor text, p_target text, p_result text, p_detail jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into migration.action_log (action, actor, target, result, detail)
  values (p_action, p_actor, left(btrim(coalesce(p_target, '')), 24), p_result, p_detail);
$$;



--
-- Name: bump_rate(text, text, integer, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.bump_rate(p_scope text, p_subject text, p_limit integer, p_window_seconds integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_win timestamptz;
  v_cnt integer;
begin
  v_win := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);

  insert into private.rate_hits (scope, subject, window_start, cnt)
  values (p_scope, p_subject, v_win, 1)
  on conflict (scope, subject, window_start)
  do update set cnt = private.rate_hits.cnt + 1
  returning cnt into v_cnt;

  return v_cnt;
end;
$$;



--
-- Name: is_space_member(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.is_space_member(p_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.space_members m
     where m.space_id = p_code
       and m.user_id  = (select auth.uid())::text
       and m.left_at is null
  );
$$;



--
-- Name: is_space_member_of(text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.is_space_member_of(p_user text, p_code text) RETURNS boolean
    LANGUAGE sql STABLE STRICT SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.space_members m
     where m.space_id = p_code and m.user_id = p_user and m.left_at is null
  );
$$;



