    from public.space_members m
   where m.user_id = (select auth.uid())::text
     and m.left_at is null;
$$;



--
-- Name: rate_limited(text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.rate_limited(p_scope text, p_subject text, p_limit_a integer, p_window_a integer, p_limit_b integer, p_window_b integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_a integer;
  v_b integer;
begin
  -- 变量逐一赋值：保证两次 INSERT 都执行（P1-1）
  v_a := private.bump_rate(p_scope || ':a', p_subject, p_limit_a, p_window_a);
  v_b := private.bump_rate(p_scope || ':b', p_subject, p_limit_b, p_window_b);
  return (v_a > p_limit_a) or (v_b > p_limit_b);
end;
$$;



--
-- Name: rpc_create_space(text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_create_space(p_nickname text, p_role text DEFAULT 'her'::text, p_start_weight numeric DEFAULT NULL::numeric, p_target_weight numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  text;
  v_code text;
  v_try  integer := 0;
  v_i    integer;
  v_role text;
  v_chars constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
begin
  v_uid := (select auth.uid())::text;
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  if private.bump_rate('space:create', v_uid, 5, 3600) > 5 then
    perform private.audit_event('space.create', v_uid, null, 'rate_limited', null);
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  -- REV3（三.1）：非法 role 拒绝，不再静默映射 'her'。
  -- 缺省参数（未传）仍为 'her'；显式传 null 或其他值 → invalid_role。
  if p_role is null or p_role not in ('her','him') then
    perform private.audit_event('space.create', v_uid, null, 'invalid_role', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_role');
  end if;
  v_role := p_role;

  if p_nickname is null or length(btrim(p_nickname)) = 0 or length(p_nickname) > 24 then
    perform private.audit_event('space.create', v_uid, null, 'invalid_nickname', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_nickname');
  end if;
  if p_start_weight is not null and (p_start_weight < 20 or p_start_weight > 400) then
    perform private.audit_event('space.create', v_uid, null, 'invalid_weight', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_weight');
  end if;
  if p_target_weight is not null and (p_target_weight < 20 or p_target_weight > 400) then
    perform private.audit_event('space.create', v_uid, null, 'invalid_weight', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_weight');
  end if;

  loop
    v_try := v_try + 1;
    v_code := 'FIT-';
    for v_i in 1..6 loop
      v_code := v_code || substr(v_chars, (get_byte(extensions.gen_random_bytes(1), 0) % 32) + 1, 1);
    end loop;
    begin
      insert into public.spaces (code, owner_status, owner_user_id)
      values (v_code, 'verified', v_uid);
      exit;
    exception when unique_violation then
      if v_try >= 5 then
        perform private.audit_event('space.create', v_uid, null, 'code_collision', null);
        return jsonb_build_object('ok', false, 'code', 'code_collision');
      end if;
    end;
  end loop;

  insert into public.space_members (space_id, user_id, role) values (v_code, v_uid, 'member');

  -- D1：档案由 RPC 创建（D1b 后客户端已无 profiles INSERT 权限）
  insert into public.profiles (owner_id, owner_name, space_id, nickname, role, start_weight, target_weight)
  values (v_uid, p_nickname, v_code, p_nickname, v_role, p_start_weight, p_target_weight)
  on conflict (owner_id, space_id) do update
     set nickname      = excluded.nickname,
         role          = excluded.role,
         start_weight  = coalesce(excluded.start_weight,  public.profiles.start_weight),
         target_weight = coalesce(excluded.target_weight, public.profiles.target_weight);

  perform private.audit_event('space.create', v_uid, v_code, 'ok', null);
  return jsonb_build_object('ok', true, 'code', v_code);
end;
$$;



--
-- Name: rpc_dissolve_space(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_dissolve_space(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid       text;
  v_code      text;
  v_arch      timestamptz;
  v_owner     text;
  v_owner_st  text;
  v_exists    boolean;
  v_arch_at   timestamptz;
begin
  v_uid := (select auth.uid())::text;
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  v_code := upper(btrim(coalesce(p_code, '')));

  -- REV3（三.4）：真单桶 3/小时（v2 双桶放行次数同为 3，但双行冗余写入）
  if private.bump_rate('space:dissolve', v_uid, 3, 3600) > 3 then
    perform private.audit_event('space.dissolve', v_uid, v_code, 'rate_limited', null);
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  select true, s.archived_at, s.owner_user_id, s.owner_status
    into v_exists, v_arch, v_owner, v_owner_st
    from public.spaces s
   where s.code = v_code
     for update;                      -- 与 join/leave 同一把锁

  if v_exists is null then
    perform private.audit_event('space.dissolve', v_uid, v_code, 'invalid_code', null);
    -- REV3（二.2）：外部与 not_owner 完全同构（存在性探测防线）
    return jsonb_build_object('ok', false, 'code', 'not_owner');
  end if;

  -- REV2（P0-1）+ REV3（二.2）：owner 判定先于 already_archived；
  -- 非 owner（无论空间是否归档）统一 not_owner，无任何附加字段。
  if v_owner_st <> 'verified' or v_owner is distinct from v_uid then
    perform private.audit_event('space.dissolve', v_uid, v_code, 'not_owner', null);
    return jsonb_build_object('ok', false, 'code', 'not_owner');
  end if;

  -- 只有真正的 owner 才能走到这里：幂等解散语义得以保留
  if v_arch is not null then
    perform private.audit_event('space.dissolve', v_uid, v_code, 'already_archived', null);
    return jsonb_build_object('ok', true, 'code', 'already_archived', 'archived_at', v_arch);
  end if;

  update public.spaces set archived_at = now() where code = v_code returning archived_at into v_arch_at;
  update public.space_members set left_at = now()
   where space_id = v_code and left_at is null;

  perform private.audit_event('space.dissolve', v_uid, v_code, 'ok', null);
  return jsonb_build_object('ok', true, 'code', 'archived', 'archived_at', v_arch_at);
end;
$$;



--
-- Name: rpc_join_space(text, text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_join_space(p_code text, p_nickname text, p_role text DEFAULT 'her'::text, p_start_weight numeric DEFAULT NULL::numeric, p_target_weight numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid    text;
  v_code   text;
  v_arch   timestamptz;
  v_exists boolean;
  v_role   text;
  v_active boolean;
begin
  v_uid := (select auth.uid())::text;
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  v_code := upper(btrim(coalesce(p_code, '')));

  -- 双桶：3/分 + 20/小时（两个桶都计数，失败同样计入）
  if private.rate_limited('space:join', v_uid, 3, 60, 20, 3600) then
    perform private.audit_event('space.join', v_uid, v_code, 'rate_limited', null);
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  -- ------------------------------------------------------------------
  -- REV3（P0-2）：参数校验全部前移 —— 成员写之前零 DML
  -- ------------------------------------------------------------------

  -- REV3（三.1）：非法 role 拒绝（与 create 对齐；缺省未传仍为 'her'）
  if p_role is null or p_role not in ('her','him') then
    perform private.audit_event('space.join', v_uid, v_code, 'invalid_role', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_role');
  end if;
  v_role := p_role;

  if p_nickname is null or length(btrim(p_nickname)) = 0 or length(p_nickname) > 24 then
    perform private.audit_event('space.join', v_uid, v_code, 'invalid_nickname', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_nickname');
  end if;
  if p_start_weight is not null and (p_start_weight < 20 or p_start_weight > 400) then
    perform private.audit_event('space.join', v_uid, v_code, 'invalid_weight', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_weight');
  end if;
  if p_target_weight is not null and (p_target_weight < 20 or p_target_weight > 400) then
    perform private.audit_event('space.join', v_uid, v_code, 'invalid_weight', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_weight');
  end if;

  -- 入口锁：锁住 spaces 行，与 dissolve 互斥（P1-4）
  select true, s.archived_at into v_exists, v_arch
    from public.spaces s
   where s.code = v_code
     for update;

  -- 持锁后重新判定：不存在 与 已归档 必须同一语义（P0-5 同理）
  if v_exists is null or v_arch is not null then
    perform private.audit_event('space.join', v_uid, v_code, 'invalid_code', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_code');
  end if;

  -- 唯一的成员写：upsert（新成员插入 / 已退出成员复活同一行）
  insert into public.space_members (space_id, user_id, role)
  values (v_code, v_uid, 'member')
  on conflict (space_id, user_id) do update
     set left_at = null, joined_at = now()
   where public.space_members.left_at is not null;

  select exists (
    select 1 from public.space_members m
     where m.space_id = v_code and m.user_id = v_uid and m.left_at is null
  ) into v_active;

  -- 防御性分支：当前顺序下 upsert 后 v_active 恒为 true
  -- （不存在 → 插入即 active；已退出 → 复活；已 active → 无行变更但仍 active）。
  -- 保留该分支作为不变量哨兵：一旦未来修改 upsert 语义，此处必须先失败。
  if not v_active then
    perform private.audit_event('space.join', v_uid, v_code, 'join_failed', null);
    return jsonb_build_object('ok', false, 'code', 'join_failed');
  end if;

  -- D1：加入即建/恢复档案（D1b 后客户端已无 profiles INSERT 权限）
  insert into public.profiles (owner_id, owner_name, space_id, nickname, role, start_weight, target_weight)
  values (v_uid, p_nickname, v_code, p_nickname, v_role, p_start_weight, p_target_weight)
  on conflict (owner_id, space_id) do update
     set nickname      = excluded.nickname,
         role          = excluded.role,
         start_weight  = coalesce(excluded.start_weight,  public.profiles.start_weight),
         target_weight = coalesce(excluded.target_weight, public.profiles.target_weight);

  perform private.audit_event('space.join', v_uid, v_code, 'ok', null);
  return jsonb_build_object('ok', true, 'code', 'joined', 'space_id', v_code);
end;
$$;



--
-- Name: rpc_leave_space(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_leave_space(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid      text;
  v_code     text;
  v_arch     timestamptz;
  v_owner    text;
  v_exists   boolean;
  v_active   integer;
begin
  v_uid := (select auth.uid())::text;
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  v_code := upper(btrim(coalesce(p_code, '')));

  -- REV3（三.4）：真单桶 10/小时（v2 双桶放行次数同为 10，但双行冗余写入）
  if private.bump_rate('space:leave', v_uid, 10, 3600) > 10 then
    perform private.audit_event('space.leave', v_uid, v_code, 'rate_limited', null);
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  select true, s.archived_at, s.owner_user_id into v_exists, v_arch, v_owner
    from public.spaces s
   where s.code = v_code
     for update;

  if v_exists is null or v_arch is not null then
    perform private.audit_event('space.leave', v_uid, v_code, 'invalid_code', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_code');
  end if;

  if not exists (
    select 1 from public.space_members m
     where m.space_id = v_code and m.user_id = v_uid and m.left_at is null
  ) then
    -- 幂等：已退出视为成功（不重复计数、不重复审计为失败）
    perform private.audit_event('space.leave', v_uid, v_code, 'already_left', null);
    return jsonb_build_object('ok', true, 'code', 'already_left');
  end if;

  if v_owner = v_uid then
    perform private.audit_event('space.leave', v_uid, v_code, 'owner_rejected', null);
    return jsonb_build_object('ok', false, 'code', 'owner_must_dissolve');
  end if;

  select count(*) into v_active
    from public.space_members m
   where m.space_id = v_code and m.left_at is null;

  if v_active <= 1 then
    perform private.audit_event('space.leave', v_uid, v_code, 'last_member', null);
    return jsonb_build_object('ok', false, 'code', 'last_member');
  end if;

  update public.space_members
     set left_at = now()
   where space_id = v_code and user_id = v_uid and left_at is null;

  delete from public.profiles where owner_id = v_uid and space_id = v_code;

  perform private.audit_event('space.leave', v_uid, v_code, 'ok', null);
  return jsonb_build_object('ok', true, 'code', 'left');
end;
$$;



--
-- Name: rpc_reward_create(text, text, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_reward_create(p_space_id text, p_condition_text text, p_target_weight numeric, p_prize text, p_promise_by text, p_owner_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  text;
  v_code text;
  v_id   bigint;
begin
  v_uid := (select auth.uid())::text;
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  -- REV3（三.4）：真单桶 20/小时
  if private.bump_rate('reward:create', v_uid, 20, 3600) > 20 then
    perform private.audit_event('reward.create', v_uid, null, 'rate_limited', null);
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  v_code := upper(btrim(coalesce(p_space_id, '')));

  if not private.is_space_member_of(v_uid, v_code) then
    perform private.audit_event('reward.create', v_uid, v_code, 'not_member', null);
    return jsonb_build_object('ok', false, 'code', 'not_member');
  end if;
  if p_promise_by is null or p_promise_by = v_uid
     or not private.is_space_member_of(p_promise_by, v_code) then
    perform private.audit_event('reward.create', v_uid, v_code, 'invalid_promisor', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_promisor');
  end if;
  if p_condition_text is null or length(btrim(p_condition_text)) = 0
     or length(p_condition_text) > 200 then
    perform private.audit_event('reward.create', v_uid, v_code, 'invalid_condition', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_condition');
  end if;
  if p_owner_name is not null and length(p_owner_name) > 24 then
    perform private.audit_event('reward.create', v_uid, v_code, 'invalid_owner_name', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_owner_name');
  end if;
  if p_prize is null or length(btrim(p_prize)) = 0 or length(p_prize) > 30 then
    perform private.audit_event('reward.create', v_uid, v_code, 'invalid_prize', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_prize');
  end if;
  if p_target_weight is not null and (p_target_weight < 20 or p_target_weight > 400) then
    perform private.audit_event('reward.create', v_uid, v_code, 'invalid_weight', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_weight');
  end if;

  insert into public.rewards
    (owner_id, owner_name, space_id, condition_text, target_weight, prize, promise_by, status)
  values
    (v_uid, p_owner_name, v_code, p_condition_text, p_target_weight, p_prize, p_promise_by, 'active')
  returning id into v_id;

  perform private.audit_event('reward.create', v_uid, v_id::text, 'ok', null);
  return jsonb_build_object('ok', true, 'code', 'created', 'id', v_id);
end;
$$;



--
-- Name: rpc_reward_delete(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_reward_delete(p_reward_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  text;
  v_r    record;
  v_rows integer;
begin
  v_uid := (select auth.uid())::text;
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  -- REV3（三.4）：真单桶 20/小时
  if private.bump_rate('reward:delete', v_uid, 20, 3600) > 20 then
    perform private.audit_event('reward.delete', v_uid, p_reward_id::text, 'rate_limited', null);
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  select r.space_id, r.owner_id into v_r
    from public.rewards r where r.id = p_reward_id
     for update;

  if v_r is null then
    -- REV3（三.3）：幂等成功补审计（v2 此分支已认证但无 action_log）
    perform private.audit_event('reward.delete', v_uid, p_reward_id::text, 'not_found', null);
    return jsonb_build_object('ok', true, 'code', 'not_found');   -- 幂等
  end if;
  if v_r.owner_id is distinct from v_uid then
    perform private.audit_event('reward.delete', v_uid, p_reward_id::text, 'not_owner', null);
    return jsonb_build_object('ok', false, 'code', 'not_owner');
  end if;
  if not private.is_space_member_of(v_uid, v_r.space_id) then
    perform private.audit_event('reward.delete', v_uid, p_reward_id::text, 'not_member', null);
    return jsonb_build_object('ok', false, 'code', 'not_member');
  end if;

  delete from public.rewards where id = p_reward_id;
  get diagnostics v_rows = row_count;

  perform private.audit_event('reward.delete', v_uid, p_reward_id::text, 'ok', null);
  return jsonb_build_object('ok', true, 'code', 'deleted', 'deleted', v_rows);
end;
$$;



--
-- Name: rpc_reward_mark_pending(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_reward_mark_pending(p_reward_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid    text;
  v_r      record;
  v_w      numeric(5,1);
  v_rows   integer;
begin
  v_uid := (select auth.uid())::text;
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  -- REV3（三.4）：真单桶 30/小时
  if private.bump_rate('reward:pending', v_uid, 30, 3600) > 30 then
    perform private.audit_event('reward.mark_pending', v_uid, p_reward_id::text, 'rate_limited', null);
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  select r.id, r.space_id, r.owner_id, r.status, r.target_weight into v_r
    from public.rewards r where r.id = p_reward_id
     for update;                       -- 行锁：并发重复调用串行化

  if v_r is null then
    perform private.audit_event('reward.mark_pending', v_uid, p_reward_id::text, 'not_found', null);
    return jsonb_build_object('ok', false, 'code', 'not_found');
  end if;
  if not private.is_space_member_of(v_uid, v_r.space_id) then
    perform private.audit_event('reward.mark_pending', v_uid, p_reward_id::text, 'not_member', null);
    return jsonb_build_object('ok', false, 'code', 'not_member');
  end if;

  -- 持锁后重新判断状态（幂等）
  if v_r.status <> 'active' then
    -- REV3（三.3）：幂等成功补审计（v2 此分支已认证但无 action_log）
    perform private.audit_event('reward.mark_pending', v_uid, p_reward_id::text, 'already', null);
    return jsonb_build_object('ok', true, 'code', 'already', 'status', v_r.status);
  end if;
  if v_r.target_weight is null then
    perform private.audit_event('reward.mark_pending', v_uid, p_reward_id::text, 'no_target', null);
    return jsonb_build_object('ok', false, 'code', 'no_target');
  end if;

  select r2.weight into v_w
    from public.records r2
   where r2.owner_id = v_r.owner_id and r2.space_id = v_r.space_id
   order by r2.record_date desc, r2.id desc
   limit 1;

  if v_w is null or v_w > v_r.target_weight then
    perform private.audit_event('reward.mark_pending', v_uid, p_reward_id::text, 'target_not_met', null);
    return jsonb_build_object('ok', false, 'code', 'target_not_met');
  end if;

  update public.rewards set status = 'pending', achieved_at = now()
   where id = p_reward_id and status = 'active';

  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    -- 理论上不可达（已持锁）；保守返回当前状态，避免"报成功但没写"
    perform private.audit_event('reward.mark_pending', v_uid, p_reward_id::text, 'race_lost', null);
    return jsonb_build_object('ok', true, 'code', 'already', 'status', 'pending');
  end if;

  perform private.audit_event('reward.mark_pending', v_uid, p_reward_id::text, 'ok', null);
  return jsonb_build_object('ok', true, 'code', 'pending');
end;
$$;



--
-- Name: rpc_reward_redeem(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_reward_redeem(p_reward_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  text;
  v_r    record;
  v_rows integer;
begin
  v_uid := (select auth.uid())::text;
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  -- REV3（三.4）：真单桶 30/小时
  if private.bump_rate('reward:redeem', v_uid, 30, 3600) > 30 then
    perform private.audit_event('reward.redeem', v_uid, p_reward_id::text, 'rate_limited', null);
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  select r.id, r.space_id, r.promise_by, r.status, r.redeemed_at into v_r
    from public.rewards r where r.id = p_reward_id
     for update;

  if v_r is null then
    perform private.audit_event('reward.redeem', v_uid, p_reward_id::text, 'not_found', null);
    return jsonb_build_object('ok', false, 'code', 'not_found');
  end if;
  if v_r.promise_by is distinct from v_uid then
    perform private.audit_event('reward.redeem', v_uid, p_reward_id::text, 'not_promisor', null);
    return jsonb_build_object('ok', false, 'code', 'not_promisor');
  end if;
  if not private.is_space_member_of(v_uid, v_r.space_id) then
    perform private.audit_event('reward.redeem', v_uid, p_reward_id::text, 'not_member', null);
    return jsonb_build_object('ok', false, 'code', 'not_member');
  end if;
  if v_r.status = 'done' then
    -- REV3（三.3）：幂等成功补审计（v2 此分支已认证但无 action_log）
    perform private.audit_event('reward.redeem', v_uid, p_reward_id::text, 'already', null);
    return jsonb_build_object('ok', true, 'code', 'already', 'status', 'done',
                              'redeemed_at', v_r.redeemed_at);
  end if;
  if v_r.status <> 'pending' then
    perform private.audit_event('reward.redeem', v_uid, p_reward_id::text, 'invalid_state', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_state');
  end if;

  update public.rewards set status = 'done', redeemed_at = now()
   where id = p_reward_id and status = 'pending';

  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    perform private.audit_event('reward.redeem', v_uid, p_reward_id::text, 'race_lost', null);
    return jsonb_build_object('ok', true, 'code', 'already', 'status', 'done');
  end if;

  perform private.audit_event('reward.redeem', v_uid, p_reward_id::text, 'ok', null);
  return jsonb_build_object('ok', true, 'code', 'done');
end;
$$;



--
-- Name: rpc_space_peek(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_space_peek(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid    text;
  v_code   text;
  v_arch   timestamptz;
  v_n      integer;
  v_names  jsonb;
begin
  v_uid := (select auth.uid())::text;
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'unauthenticated');
  end if;

  v_code := upper(btrim(coalesce(p_code, '')));

  if private.rate_limited('space:peek', v_uid, 5, 60, 30, 3600) then
    perform private.audit_event('space.peek', v_uid, v_code, 'rate_limited', null);
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  -- REV2 修正：**不做格式前置校验**。
  -- v1 曾在此按新码正则提前拒绝，但历史导入的空间码可能不合规
  -- （NOT VALID 阶段 D/F 之前），格式闸门会让合法的旧空间无法 peek。
  -- 归一化后未命中的码自然落入"不存在 → invalid_code"，语义一致；
  -- 任意长输入不会进入 action_log（audit_event 内截断 24 字符）。

  select s.archived_at into v_arch from public.spaces s where s.code = v_code;

  -- 不存在(FOUND=false) 与 已归档 统一语义
  if not found or v_arch is not null then
    perform private.audit_event('space.peek', v_uid, v_code, 'invalid_code', null);
    return jsonb_build_object('ok', false, 'code', 'invalid_code');
  end if;

  -- 空成员空间（P0-6 / REV2 定案）：count=0、names=[]，**不是错误**。
  --   该状态只在历史导入可达（verified 空间的 owner 不可退出、
  --   末位成员退出被拒、归档空间已被上面拦掉）。
  --   peek 的语义是"该码当前有多少人"，0 是合法答案；是否加入由用户决定。
  select count(*)::integer,
         coalesce(
           jsonb_agg(left(coalesce(nullif(btrim(p.nickname), ''), '?'), 1) || '**' order by m.id),
           '[]'::jsonb
         )
    into v_n, v_names
    from public.space_members m
    left join public.profiles p
           on p.space_id = m.space_id and p.owner_id = m.user_id
   where m.space_id = v_code
     and m.left_at is null;

  perform private.audit_event('space.peek', v_uid, v_code, 'ok',
                              jsonb_build_object('count', v_n));
  return jsonb_build_object('ok', true, 'code', 'found', 'count', v_n, 'names', v_names);
end;
$$;



