    CONSTRAINT rewards_status_chk CHECK ((status = ANY (ARRAY['active'::text, 'pending'::text, 'done'::text]))),
    CONSTRAINT rewards_ts_chk CHECK ((((status = 'active'::text) AND (achieved_at IS NULL) AND (redeemed_at IS NULL)) OR ((status = 'pending'::text) AND (achieved_at IS NOT NULL) AND (redeemed_at IS NULL)) OR ((status = 'done'::text) AND (achieved_at IS NOT NULL) AND (redeemed_at IS NOT NULL))))
);



