GRANT ALL ON TABLE public.todos TO service_role;
GRANT SELECT,DELETE ON TABLE public.todos TO authenticated;


--
-- Name: COLUMN todos.owner_id; Type: ACL; Schema: public; Owner: postgres
--

GRANT INSERT(owner_id) ON TABLE public.todos TO authenticated;


--
-- Name: COLUMN todos.owner_name; Type: ACL; Schema: public; Owner: postgres
--

GRANT INSERT(owner_name) ON TABLE public.todos TO authenticated;


--
-- Name: COLUMN todos.space_id; Type: ACL; Schema: public; Owner: postgres
--

GRANT INSERT(space_id) ON TABLE public.todos TO authenticated;


--
-- Name: COLUMN todos.text; Type: ACL; Schema: public; Owner: postgres
--

GRANT INSERT(text) ON TABLE public.todos TO authenticated;


--
-- Name: COLUMN todos.sort; Type: ACL; Schema: public; Owner: postgres
--

GRANT INSERT(sort) ON TABLE public.todos TO authenticated;


--
-- Name: SEQUENCE todos_id_seq; Type: ACL; Schema: public; Owner: postgres
--

GRANT ALL ON SEQUENCE public.todos_id_seq TO anon;
GRANT ALL ON SEQUENCE public.todos_id_seq TO authenticated;
GRANT ALL ON SEQUENCE public.todos_id_seq TO service_role;


--

REVOKE ALL ON SCHEMA migration FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA migration, private FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA migration, private FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA private FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA private TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_space_member(text), private.my_space_ids() TO authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon;
ALTER TABLE private.rate_hits ENABLE ROW LEVEL SECURITY;
ALTER TABLE migration.action_log ENABLE ROW LEVEL SECURITY;
SET check_function_bodies = true;
NOTIFY pgrst, 'reload schema';
COMMIT;
